def eulerian_num(n, m):
    if n < 0 or m < 0 or m >= n and not (n == 0 and m == 0):
        return 0
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(0, i):
            val = 0
            if j - 1 >= 0:
                val += (i - j) * dp[i - 1][j - 1]
            val += (j + 1) * dp[i - 1][j]
            dp[i][j] = val
    return dp[n][m]

