def amicable_numbers_sum(limit):
    if limit < 2:
        return 0

    # sum_div[n] will store the sum of proper divisors of n
    sum_div = [0] * (limit + 1)

    # For each divisor d, add it to all multiples of d greater than d
    for d in range(1, limit // 2 + 1):
        for multiple in range(2 * d, limit + 1, d):
            sum_div[multiple] += d

    total = 0
    for a in range(2, limit + 1):
        b = sum_div[a]
        if b != a and b <= limit and b >= 1 and sum_div[b] == a:
            total += a

    return total

