def is_Sum_Of_Powers_Of_Two(n):
    # A number can be represented as a sum of non-zero powers of 2
    # iff it is a positive integer. This can be verified by repeatedly
    # removing powers of 2 from its binary representation.
    if not isinstance(n, int) or n <= 0:
        return False

    while n > 0:
        # Remove the lowest set bit (a power of 2).
        n &= n - 1

    return True

