def is_majority(arr, n, x):
    low, high = 0, n - 1
    first = -1

    # Find first occurrence of x using binary search
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            first = mid
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if first == -1:
        return False

    check_index = first + n // 2
    return check_index < n and arr[check_index] == x

